import { Product } from 'src/app/model/Product';
import { Component, EventEmitter, Input, Output } from '@angular/core';
import { CartService } from 'src/app/services/cart.service';

@Component({
  selector: 'app-card',
  templateUrl: './card.component.html',
  styleUrls: ['./card.component.scss']
})
export class CardComponent {
  @Input() product!: Product;
  @Output() viewDetails = new EventEmitter<number>();

 constructor(private cartService: CartService) {}
   onAddToCart(product: Product) {

    this.cartService.addToCart(product.id,quantity).subscribe({
      next: (response) => console.log('Added to cart:', response),
      error: (err) => console.error('Error adding to cart:', err),
    });
  }
  viewDetailsEvent() {
    console.log('Card clicked, emitting product id:', this.product?.id);
    if (this.product && this.product.id !== undefined && this.product.id !== null) {
      this.viewDetails.emit(this.product.id);
    }
  }
}
